"""Host stdlib checker; contract expectations never come from reader output."""
import sys,json
from pathlib import Path
E=Path(__file__).parents[2]/'evidence/implementation-r013'
cases=json.loads((E/'cases-005.json').read_text())['cases']
rows=json.loads(Path(sys.argv[1]).read_text());checks=[]
def types(x):
    if isinstance(x,dict):
        if 't' in x:yield x['t']
        for v in x.values():yield from types(v)
    elif isinstance(x,list):
        for v in x:yield from types(v)
by_id={c['id']:c for c in cases}
for r in rows:
    c=by_id[r['id']]
    assert c['id']==r['id']
    visits=[{k:v[k] for k in ['snippet','char','byte']} for v in r['visits']]
    tests={'no_error':r['error'] is None,'first_detail':(c['detail'] in (r['detail'] or '')) if c['detail'] else r['detail'] is None,
           'visits_exact':visits==c['visits']}
    if c.get('asset'):
        a=r['audit'];o=r['observation'];refs=[v for n in (o or {}).get('nodes',[]) for v in n.get('references',[])]
        tests['asset_or_explicit_residual']=any(v.get('uri')=='p.png' for v in a.get('assets',[])) or (a.get('status')=='INCOMPLETE' and a.get('reason')=='UNSUPPORTED_RESOURCE_SYNTAX' and any(u.get('resource_syntax') and u.get('raw') and u.get('source_position') for u in a.get('unknown',[])))
    if c.get('code_owned'):
        tests['owned_inert']=not r['visits'] and r['detail'] is None
    if r['observation']:
        tests['coverage_private']='_guard_coverage' not in json.dumps(r['observation'])
    if 'pandoc' in r:
        ts=list(types(r['pandoc']['ast']))
        # Pandoc evidence established list/backticks without blank as Code
        # inline; see oracle-corrections-001.json. Both are real literal owners.
        if not c.get('format'):
            def owners(x):
                if isinstance(x,dict):
                    if x.get('t') in ('CodeBlock','Code') and any(t in str(x.get('c')) for t in ('<script','<img')):yield x['t']
                    for v in x.values():yield from owners(v)
                elif isinstance(x,list):
                    for v in x:yield from owners(v)
            tests['AST_literal_owner']=bool(list(owners(r['pandoc']['ast'])))==c['code_owned']
    checks.append({'id':c['id'],'tests':tests,'failed':[k for k,v in tests.items() if not v]})
value={'cases':len(checks),'met':sum(not r['failed'] for r in checks),'rows':checks}
Path(sys.argv[2]).write_text(json.dumps(value,indent=2)+'\n')
print(value['met'],'/',value['cases'])
for r in checks:
    if r['failed']:print(r['id'],','.join(r['failed']))

