"""Independent arithmetic/binding of 64 outputs; no product imports."""
import functools,hashlib,json
from pathlib import Path
R=Path.cwd();E=R/'temp/run-a002-fase1-corpus/evidence/implementation-r013'
def read(p):return json.loads(Path(p).read_text())
def desc(p):
 p=Path(p);b=p.read_bytes();return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
@functools.lru_cache(maxsize=64)
def distance(a,b):
 matrix=[[0]*(len(b)+1) for _ in range(len(a)+1)]
 for i in range(len(a)+1):matrix[i][0]=i
 for j in range(len(b)+1):matrix[0][j]=j
 for i in range(1,len(a)+1):
  for j in range(1,len(b)+1):matrix[i][j]=min(matrix[i-1][j]+1,matrix[i][j-1]+1,matrix[i-1][j-1]+(a[i-1]!=b[j-1]))
 return matrix[-1][-1]
def soft(v):return v.replace('\r\n','\n').replace('\r','\n').replace('\n',' ').strip(' ')
summary=read(E/'rescore-002/summary.json');checks=[]
for row in summary['records']:
 for key in ('metrics','observations','audit','gold','verification','run','old_metrics','old_observations','old_audit','previous_derived_final','conversion_final'):
  assert desc(row[key]['path'])==row[key]
 native=read(row['conversion_final']['path']);previous=read(row['previous_derived_final']['path']);assert native['run']==previous['run']==row['run']
 for key in ('metrics','observations','audit'):assert previous[key]==row['old_'+key]
 m=read(row['metrics']['path']);g=read(row['gold']['path']);o=read(row['observations']['path']);old=read(row['old_metrics']['path']);d=m['WER_decomposition'];entries=d['entries']
 for v in entries:
  assert v['known_word_edits']==v['conditional_word_edits'] and v['guaranteed_bound'] is False
  if v['category']=='aligned_block_edits' and v['status']=='KNOWN':assert v['known_word_edits']==distance(tuple(v['expected_text'].split()),tuple(v['actual_text'].split()))
  if v['category']=='expected_omission' and v['status']=='KNOWN':assert v['known_word_edits']==len(v['text'].split())
  if v['category']=='unmatched_observed_insertion' and v['status']=='KNOWN':assert v['known_word_edits']==len(v['text'].split())
  for role in v.get('role_candidates',[]):
   block=next(b for b in g['blocks'] if b['block_id']==role['block_id']);assert role['text']==v['text']==(block['caption'] if role['role']=='caption' else block['text'])
 assert sum(v['reference_words'] for v in entries)==m['totals']['word_ref']
 assert sum(v['conditional_word_edits'] for v in entries)==m['totals']['word_errors']
 assert d['categories']=={cat:sum(v['conditional_word_edits'] for v in entries if v['category']==cat) for cat in ['aligned_block_edits','expected_omission','unmatched_observed_insertion']}
 gs=g['blocks']
 if g.get('note_order_policy')=='definitions-collected-at-end':gs=[b for b in gs if b['type']!='note']+[b for b in gs if b['type']=='note']
 expected=[];actual=[]
 for b in gs:
  if b['type'] in ('formula','table','figure','anchor'):continue
  value=b['text']
  refs=[v for v in b.get('references',[]) if row['format']=='epub' or row['format'] in ('docx','rtf','tex') and v['kind']=='link']
  value+=''.join(' '+v['text'] for v in refs)
  value=value if b['type'] in ('code','literal_text') else soft(value)
  if value:expected.append(value)
 for n in o['nodes']:
  if n['type'] in ('formula','table','figure','anchor'):continue
  value=n.get('text','');value=value if n['type']=='code' else soft(value)
  if value:actual.append(value)
 bound=m['text_lower_bound'];assert bound['guaranteed'] and bound['reference_words']==m['totals']['word_ref']
 if bound['status']=='EXACT_GLOBAL_DISTANCE':
  independent_words=distance(tuple(' '.join(expected).split()),tuple(' '.join(actual).split()));independent_chars=distance('\n'.join(expected),'\n'.join(actual))
  assert bound['word_errors']==independent_words and bound['char_errors']==independent_chars
 else:assert bound['status']=='TRIVIAL_ZERO' and bound['word_errors']==bound['char_errors']==0 and m['WER'] is None
 # Report actual differences; no assertion to force the old campaign counts.
 deltas={key:{'old':old[key],'new':m[key]} for key in ('quality','automatic_gates','score_exit','totals','denominators','CER','WER','blocks','order','pages','text_metric_availability','WER_decomposition','conditional_text_counts','text_lower_bound','alignment','failures','unavailable','details','metrics_version') if m[key]!=old[key]}
 checks.append({'id':row['derived_measurement_id'],'metrics':row['metrics'],'conditional_categories':d['categories'],'conditional_words':m['totals']['word_errors'],'reference_words':m['totals']['word_ref'],'guaranteed_bound':bound,'actual_numeric_gate_delta':deltas,'raw_byte_identity':Path(row['root']+'/raw/document.md').read_bytes()==Path(row['metrics']['path']).parent.joinpath('raw/document.md').read_bytes()})
 assert checks[-1]['raw_byte_identity']
 def raw_tree(root):
  return {str(p.relative_to(root)):(p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest()) for p in root.rglob('*') if p.is_file() and not p.is_symlink()}
 assert raw_tree(Path(row['root'])/'raw')==raw_tree(Path(row['metrics']['path']).parent/'raw')
 final=read(Path(row['metrics']['path']).parent/'final.json');assert final==row
 assert o['reader']=='observations-v13-ordered-guards-fences' and m['metrics_version']=='metrics-v4-conditional-and-bounds'
 assert row['engine_runs']==0 and row['not_a_new_conversion_attempt']

result={'status':'PASS','checker':desc(__file__),'attempts':len(checks),'checks':checks,'engine_runs':0,'independent_oracle':'full edit matrix for conditional tokens/global characters+tokens; cached only for identical actual string pairs; no reader/scorer/generator imports','numeric_gate_differences':sum(bool(v['actual_numeric_gate_delta']) for v in checks)}
assert len(checks)==64
with (E/'derived-check-002.json').open('x') as f:json.dump(result,f,ensure_ascii=False,indent=2)
print('DERIVED CHECK PASS',len(checks),'numeric/gate differences',result['numeric_gate_differences'])

