"""Confronto JSON indipendente; privati distinti dalle metriche."""
import json,hashlib
from pathlib import Path
E=Path.cwd()/'temp/run-a002-fase1-corpus/evidence/implementation-r013'
def read(p):return json.loads(Path(p).read_text())
def delta(a,b,path='$'):
    if isinstance(a,dict) and isinstance(b,dict):
        for k in sorted(a.keys()|b.keys()):
            if k not in b:yield {'path':path+'.'+k,'kind':'removed','old':a[k]}
            elif k not in a:yield {'path':path+'.'+k,'kind':'added','new':b[k]}
            else:yield from delta(a[k],b[k],path+'.'+k)
    elif isinstance(a,list) and isinstance(b,list) and len(a)==len(b):
        for i,(x,y) in enumerate(zip(a,b)):yield from delta(x,y,f'{path}[{i}]')
    elif a!=b:yield {'path':path,'kind':'changed','old':a,'new':b}
rows=[]
for r in read(E/'rescore-002/summary.json')['records']:
    changes=list(delta(read(r['old_observations']['path']),read(r['observations']['path'])))
    private=[d for d in changes if d['path'].endswith('._guard_coverage')]
    other=[d for d in changes if d not in private and d['path']!='$.reader']
    rows.append({'id':r['derived_measurement_id'],'old':r['old_observations'],'new':r['observations'],
                 'private_removals':len(private),'private_kinds':sorted({d['kind'] for d in private}),
                 'reader_id_delta':next((d for d in changes if d['path']=='$.reader'),None),'other':other})
result={'attempts':len(rows),'private_removals':sum(r['private_removals'] for r in rows),
        'attempts_with_private_removals':sum(bool(r['private_removals']) for r in rows),
        'attempts_with_other_delta':sum(bool(r['other']) for r in rows),'records':rows,
        'checker_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
with (E/'observation-delta-002.json').open('x') as f:json.dump(result,f,ensure_ascii=False,indent=2);f.write('\n')
print({k:v for k,v in result.items() if k!='records'})
